@Override
public void endElement(String uri, String localName, String qName) throws SAXException {
    ensureNotEnded("endElement </" + display(qName, localName) + ">");
    if (openElements.isEmpty()) {
        throw new SAXException("StrictXHTMLValidator: endElement </" + display(qName, localName) + "> with no matching startElement");
    }
    QName top = openElements.pop();
    if (!top.matches(uri, localName, qName)) {
        throw new SAXException("StrictXHTMLValidator: endElement </" + display(qName, localName) + "> does not match topmost open element <" + top.qOrLocal() + ">");
    }
    super.endElement(uri, localName, qName);
}
